1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	export type Damage = { itemType: string; amount: number };
8	export type Incident = { cause: string; damages: Damage[] };
9	
10	export type Step = {
11	  op: string;
12	  items?: Item[];
13	  policy?: number;
14	  incident?: Incident;
15	};
16	export type Customer = { yearsWithMHPCO: number };
17	export type Scenario = { customer: Customer; steps: Step[] };
18	
19	export type QuoteResult = { premium: number };
20	export type ClaimResult = { payout: number; remainingCap: number };
21	export type StepResult = QuoteResult | ClaimResult;
22	export type ScenarioResult = { results: StepResult[] };
23	
24	const BASE_PREMIUMS: Record<string, number> = {
25	  sword: 100,
26	  amulet: 60,
27	  staff: 80,
28	  potion: 40,
29	  rune: 25,
30	  moonstone: 25,
31	};
32	
33	const INSURANCE_VALUES: Record<string, number> = {
34	  sword: 1000,
35	  amulet: 600,
36	  staff: 800,
37	  potion: 400,
38	  rune: 250,
39	  moonstone: 250,
40	};
41	
42	const DEDUCTIBLE_PER_DAMAGE = 100;
43	const CAP_MULTIPLIER = 2;
44	const HALVED_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
45	const HALVED_REIMBURSEMENT_RATE = 0.5;
46	
47	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
48	const PROCESSING_FEE = 5;
49	
50	const CURSE_SURCHARGE_RATE = 0.5;
51	const SURCHARGED_ENCHANTMENT_LEVEL = 5;
52	const ENCHANTMENT_SURCHARGE_RATE = 0.3;
53	const LOYALTY_THRESHOLD_YEARS = 2;
54	const LOYALTY_DISCOUNT_RATE = 0.2;
55	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
56	
57	const BLOCK_SIZE = 3;
58	const BLOCK_BASE_PREMIUM = 60;
59	
60	const sum = (amounts: number[]): number =>
61	  amounts.reduce((total, amount) => total + amount, 0);
62	
63	const countByType = (items: Item[]): Map<string, number> => {
64	  const counts = new Map<string, number>();
65	  for (const item of items) {
66	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
67	  }
68	  return counts;
69	};
70	
71	const basePremiumForType = (type: string, count: number): number =>
72	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
73	
74	const policyBasePremium = (items: Item[]): number =>
75	  sum(
76	    [...countByType(items)].map(([type, count]) =>
77	      basePremiumForType(type, count),
78	    ),
79	  );
80	
81	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
82	
83	const isCursed = (item: Item): boolean => item.cursed === true;
84	
85	const attractsEnchantmentSurcharge = (item: Item): boolean =>
86	  (item.enchantment ?? 0) >= SURCHARGED_ENCHANTMENT_LEVEL;
87	
88	const curseSurcharge = (item: Item): number =>
89	  isCursed(item) ? itemBasePremium(item) * CURSE_SURCHARGE_RATE : 0;
90	
91	const enchantmentSurcharge = (item: Item): number =>
92	  attractsEnchantmentSurcharge(item)
93	    ? itemBasePremium(item) * ENCHANTMENT_SURCHARGE_RATE
94	    : 0;
95	
96	const itemModifierSurcharges = (items: Item[]): number =>
97	  sum(items.map((item) => curseSurcharge(item) + enchantmentSurcharge(item)));
98	
99	const isLoyalCustomer = (customer: Customer): boolean =>
100	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
101	
102	// Policy-wide modifiers are rates applied to the policy base premium.
103	// Surcharges are positive, discounts negative; they sum to one net rate.
104	const policyModifierRates = (
105	  customer: Customer,
106	  isFollowUpContract: boolean,
107	): number[] => [
108	  FIRST_INSURANCE_SURCHARGE_RATE,
109	  isLoyalCustomer(customer) ? -LOYALTY_DISCOUNT_RATE : 0,
110	  isFollowUpContract ? -FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0,
111	];
112	
113	const netPolicyModifierRate = (
114	  customer: Customer,
115	  isFollowUpContract: boolean,
116	): number => sum(policyModifierRates(customer, isFollowUpContract));
117	
118	const quotePremium = (
119	  customer: Customer,
120	  items: Item[] = [],
121	  isFollowUpContract = false,
122	): number => {
123	  const policyBase = policyBasePremium(items);
124	  const policyModifiers =
125	    policyBase * netPolicyModifierRate(customer, isFollowUpContract);
126	  return Math.ceil(
127	    policyBase +
128	      itemModifierSurcharges(items) +
129	      policyModifiers +
130	      PROCESSING_FEE,
131	  );
132	};
133	
134	type Policy = { items: Item[]; remainingCap: number };
135	
136	const insuranceSum = (items: Item[]): number =>
137	  sum(items.map((item) => INSURANCE_VALUES[item.type]));
138	
139	const hasHalvedReimbursement = (item: Item): boolean =>
140	  (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_ENCHANTMENT_LEVEL;
141	
142	const reimbursedAmount = (item: Item, damage: Damage): number =>
143	  hasHalvedReimbursement(item)
144	    ? damage.amount * HALVED_REIMBURSEMENT_RATE
145	    : damage.amount;
146	
147	const damagePayout = (item: Item, damage: Damage): number =>
148	  reimbursedAmount(item, damage) - DEDUCTIBLE_PER_DAMAGE;
149	
150	type ClaimedItem = { item: Item; damage: Damage };
151	
152	// Each damage entry is matched to a distinct insured item, so a policy
153	// covering two swords can absorb two separate sword damages. Pairing the
154	// two up here keeps the correspondence in the data, rather than leaving
155	// callers to line up two arrays by index.
156	// Removes and returns the first item of the wanted type, so that each item
157	// can be claimed against at most once. A damage with no item left to match
158	// is not covered — either the type was never insured, or every insured item
159	// of that type has already been claimed against in this same incident.
160	const takeItemOfType = (unclaimed: Item[], itemType: string): Item => {
161	  const matchIndex = unclaimed.findIndex((item) => item.type === itemType);
162	  if (matchIndex === -1) {
163	    throw new Error(
164	      `Damage reported for a ${itemType} that is not covered by this policy`,
165	    );
166	  }
167	  return unclaimed.splice(matchIndex, 1)[0];
168	};
169	
170	const matchDamagesToItems = (
171	  policy: Policy,
172	  damages: Damage[],
173	): ClaimedItem[] => {
174	  const unclaimed = [...policy.items];
175	  return damages.map((damage) => ({
176	    item: takeItemOfType(unclaimed, damage.itemType),
177	    damage,
178	  }));
179	};
180	
181	// Payouts are summed as exact fractions and only then rounded down, so that
182	// rounding happens once per claim rather than once per damaged item.
183	const desiredPayout = (policy: Policy, incident: Incident): number =>
184	  Math.floor(
185	    sum(
186	      matchDamagesToItems(policy, incident.damages).map(({ item, damage }) =>
187	        damagePayout(item, damage),
188	      ),
189	    ),
190	  );
191	
192	const settleClaim = (policy: Policy, incident: Incident): ClaimResult => {
193	  const payout = Math.min(desiredPayout(policy, incident), policy.remainingCap);
194	  policy.remainingCap -= payout;
195	  return { payout, remainingCap: policy.remainingCap };
196	};
197	
198	const openPolicy = (items: Item[]): Policy => ({
199	  items,
200	  remainingCap: insuranceSum(items) * CAP_MULTIPLIER,
201	});
202	
203	export const runScenario = (scenario: Scenario): ScenarioResult => {
204	  // Policies are keyed by the index of the quote step that opened them;
205	  // a claim step names that index in `step.policy`.
206	  const policies = new Map<number, Policy>();
207	
208	  const quoteStep = (step: Step, stepIndex: number): QuoteResult => {
209	    for (const item of step.items ?? []) {
210	      if (!(item.type in BASE_PREMIUMS)) {
211	        throw new Error(`Unknown item type: ${item.type}`);
212	      }
213	    }
214	    // A quote is a follow-up when some earlier step already opened a policy,
215	    // so this must be read before the new policy is registered below.
216	    const isFollowUpContract = policies.size > 0;
217	    const items = step.items ?? [];
218	    policies.set(stepIndex, openPolicy(items));
219	    return {
220	      premium: quotePremium(scenario.customer, items, isFollowUpContract),
221	    };
222	  };
223	
224	  const claimStep = (step: Step): ClaimResult =>
225	    settleClaim(policies.get(step.policy ?? -1)!, step.incident!);
226	
227	  const results = scenario.steps.map((step, stepIndex): StepResult =>
228	    step.op === "claim" ? claimStep(step) : quoteStep(step, stepIndex),
229	  );
230	
231	  return { results };
232	};
